definitionCode.python:
class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

definitionCode.javascript:
class Node {
    constructor(val = 0, next = null) {
        this.val = val;
        this.next = next;
    }
}

definitionCode.java:
class ListNode {
    int val;
    ListNode next;
    ListNode(int val) { this.val = val; }
}

definitionCode.cpp:
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

code.javascript:
const newNode = new Node(5);
newNode.next = head;
head = newNode;

code.java:
ListNode newNode = new ListNode(5);
newNode.next = head;
head = newNode;

code.cpp:
ListNode* newNode = new ListNode(5);
newNode->next = head;
head = newNode;

code.javascript:
let curr = head;
while (curr) {
    console.log(curr.val);
    curr = curr.next;
}

code.java:
ListNode curr = head;
while (curr != null) {
    System.out.println(curr.val);
    curr = curr.next;
}

code.cpp:
ListNode* curr = head;
while (curr != nullptr) {
    cout << curr->val << endl;
    curr = curr->next;
}

code.javascript:
let prev = null, curr = head;
while (curr) {
    let nxt = curr.next;
    curr.next = prev;
    prev = curr;
    curr = nxt;
}
return prev;

code.java:
ListNode prev = null, curr = head;
while (curr != null) {
    ListNode nxt = curr.next;
    curr.next = prev;
    prev = curr;
    curr = nxt;
}
return prev;

code.cpp:
ListNode* prev = nullptr;
ListNode* curr = head;
while (curr != nullptr) {
    ListNode* nxt = curr->next;
    curr->next = prev;
    prev = curr;
    curr = nxt;
}
return prev;
